WITH left_oracle AS (WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,ma3>ma30 AND LAG(ma3) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)<=LAG(ma30) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic_technical`), qualified AS (SELECT mktcode,tgtcode FROM event_rows WHERE bizdate>=DATE_TRUNC('2026-04-14','YEAR') AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14'), right_oracle AS (WITH scoped AS (SELECT q.mktcode,q.tgtcode,q.bizdate,(q.lastPx/10000.0)*q.totalShare AS metric FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate='2026-04-14' AND (q.mktcode=1 AND q.tgtcode BETWEEN '688000' AND '688999')), industry_stat AS (SELECT i.industry_code,MIN(s.metric) AS baseline FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' GROUP BY i.industry_code) SELECT s.mktcode,s.tgtcode,s.bizdate FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode INNER JOIN industry_stat a ON a.industry_code=i.industry_code WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' AND s.metric>a.baseline), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=100), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=10) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
